select case when s.rating >= 4.3 then 'high' when s.rating >= 1.8 then 'mid' else 'low' end as rating_bucket, s.city, min(p.launch_date) as first_launch_date, count(distinct p.cost) as unique_brands from products p full outer join suppliers s on p.supplier_id = s.id group by case when s.rating >= 4.3 then 'high' when s.rating >= 1.8 then 'mid' else 'low' end, s.city order by city, unique_brands desc
